-- =====================================================================
-- 0018 — صفحة التعريف خلف رمز اطّلاع (ملاحظة ٩١)
--   محتوى الصفحة لا يُرسل إلى المتصفح إلا بعد التحقق: إمّا عضو مفعّل
--   في المنصة، وإمّا زائر يكتب رمز الاطّلاع الذي تعطيه الإدارة.
--   فليس في ملفات الواجهة نصٌّ يمكن قراءته دون إذن.
-- =====================================================================

create table if not exists public.page_content (
  key        text primary key,
  content    jsonb not null,
  code_hash  text,                 -- bcrypt لرمز الاطّلاع، فارغ يعني مفتوحة للجميع
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id)
);

alter table public.page_content enable row level security;
-- لا سياسة قراءة: لا يصل أحد إلى الجدول إلا عبر الدوال أدناه
drop policy if exists "manager reads pages" on public.page_content;
create policy "manager reads pages" on public.page_content for select using (public.is_manager());

insert into public.page_content (key, content) values ('about', '{"badge":"مبادرة من إدارة مشروع خادم الحرمين الشريفين لترجمة خطب الحرمين الشريفين","h1":"منصة إدارة ترجمة خطب الحرمين الشريفين","lead":"عرض تعريفي شامل: الرؤية والرسالة، وآلية العمل، والاستضافة داخل المملكة، وإجراءات السرية، وآلية الإدارة والمخرجات.","note":"هذه الصفحة وصف لما هو قائم ومطبَّق في المنصة اليوم، لا لما هو مخطط له، عدا القسم الأخير.","vision":"أن يبلغ خطابُ الحرمين الشريفين كلَّ قاصدٍ ومستمعٍ بلغته، في وقته، بضبطٍ يليق بالمكان.","mission":"إدارةُ أعمال ترجمة خطب الحرمين الشريفين ودروسِهما وموادِّ الهيئة في منصةٍ رسميةٍ واحدة — من استلام الأصل إلى اعتماد الترجمة — بفريقٍ مؤهَّل، ومراحلَ وصلاحياتٍ مضبوطة، وسريةٍ محفوظةٍ حتى النشر، وبياناتٍ لا تغادر المملكة.","stats":[["50","لغة مهيّأة في المنصة"],["13","لغة رئيسية معتمدة"],["6","مراحل لكل لغة"],["100%","داخل المملكة"],["يوميًّا","نسخ احتياطي مشفّر"]],"goals":["التوسع في اللغات فوق الخمسين المتاحة اليوم، بحسب حاجة قاصدي الحرمين الشريفين.","تقصير الزمن بين إلقاء الخطبة ونشر ترجمتها المعتمدة.","ألّا تُنشر ترجمة إلا بعد مراجعة شرعية ولغوية واعتماد.","بناء فريق مؤهَّل موثَّق: اختبار في اللغة، وتقييم للأداء، وبطاقة عمل رسمية.","حفظ أرشيف دائم لخطب الحرمين الشريفين وترجماتها يُرجع إليه.","إبقاء العمل وبياناته على بنية داخل المملكة، بلا ارتهان لمزوّد خارجي."],"stages":[["الترجمة","المترجم","ينقل المادة إلى لغته داخل المنصة، على كليشة الهيئة، بمساحة كتابة ثابتة."],["المراجعة الشرعية","مراجع","يتحقق من سلامة المعاني الشرعية ودقة نقل النصوص والأدلة."],["المراجعة اللغوية","مراجع","يتحقق من سلامة الأسلوب والقواعد في اللغة المترجَم إليها."],["التحرير","محرر","ضبط الصياغة والعناوين والتنسيق قبل الرفع."],["استلام المنسق","المنسق","يستلم العمل ويطابقه بالأصل ويعيده إن لزم بملاحظة مكتوبة."],["اعتماد مدير المشروع","مدير المشروع","يعتمد النشر، وعندها تدخل المادة الأرشيف وتتاح للنشر."]],"roles":[["مدير المشروع",["اعتماد النشر، وإنشاء الحسابات وتحديد الأدوار.","إعداد سير العمل والمراحل والمواعيد.","اعتماد بطاقات العمل وتوثيق الحسابات البنكية.","حذف الأعمال من الأرشيف واسترجاعها."]],["المنسق",["إدخال المواد وإسناد اللغات وتحديد المواعيد.","مراجعة طلبات التسجيل وتفعيل الحسابات.","استلام الأعمال وردّها بملاحظة، وتحديد مواضع التعديل على الأصل.","إرسال التعاميم ومتابعة التوقيع عليها."]],["المترجم والمراجع",["استلام ما يُسند إليه في لغاته وحدها.","العمل داخل المنصة على كليشة الهيئة.","رفع التسجيل الصوتي حين يُطلب.","إدارة بياناته الشخصية وحسابه البنكي وبطاقته."]]],"sections":[["vision","الرؤية والرسالة",[["vision"],["h3","الأهداف"],["ul",["التوسع في اللغات فوق الخمسين المتاحة اليوم، بحسب حاجة قاصدي الحرمين الشريفين.","تقصير الزمن بين إلقاء الخطبة ونشر ترجمتها المعتمدة.","ألّا تُنشر ترجمة إلا بعد مراجعة شرعية ولغوية واعتماد.","بناء فريق مؤهَّل موثَّق: اختبار في اللغة، وتقييم للأداء، وبطاقة عمل رسمية.","حفظ أرشيف دائم لخطب الحرمين الشريفين وترجماتها يُرجع إليه.","إبقاء العمل وبياناته على بنية داخل المملكة، بلا ارتهان لمزوّد خارجي."]]]],["purpose","الغاية",[["p","هذه المنصة مبادرة من إدارة مشروع خادم الحرمين الشريفين لترجمة خطب الحرمين الشريفين، بُنيت داخل المشروع لخدمة عمله."],["p","منصة رسمية واحدة تُدار بها ترجمة خطب المسجد الحرام والمسجد النبوي ودروسهما وموادّ الهيئة إلى لغات العالم، من لحظة وصول الأصل العربي إلى لحظة اعتماد الترجمة ونشرها."],["p","الغاية أن يصل خطاب الحرمين الشريفين إلى قاصديهما بلغاتهم، بضبط يليق بالمكان: عمل موثّق، ومواعيد محكومة، ومسؤولية معلومة في كل مرحلة."]]],["problem","ما الذي تعالجه",[["p","قبل المنصة كان العمل يجري عبر وسائل متفرقة: مجموعات محادثة، ورسائل بريد، وملفات تُتداول بين الأجهزة. ونتج عن ذلك:"],["ul",["تداول المادة السرية خارج نطاق مضبوط قبل نشرها.","تعذّر معرفة موضع كل لغة: من يعمل عليها الآن؟ وفي أي مرحلة؟ ومتى موعدها؟","ضياع النسخ وتعدّدها، وصعوبة معرفة النسخة المعتمدة.","غياب سجل يُرجع إليه عند المساءلة أو التقييم.","اعتماد العمل على أشخاص بأعيانهم، فإذا غابوا تعطّل."]],["p","المنصة تجمع ذلك كله في مكان واحد: المادة، والمراحل، والمواعيد، والسجل، والصلاحيات."]]],["flow","دورة العمل",[["p","تُدخَل المادة مرة واحدة، ثم تُسند لغاتها. وكل لغة مسار مستقل يمر بست مراحل، لكل مرحلة مسؤول وموعد:"],["stages"],["p","المنسق يختار المراحل اللازمة لكل مادة؛ فليست كل مادة تحتاج مراجعتين. وإذا رُدّت مرحلة إلى سابقتها لزم بيان السبب كتابةً، ويُسجَّل ذلك في سجل المادة."],["p","وإذا عُدِّل الأصل بعد اعتماده — وهو ما يقع حين يعدّل الشيخ نصه — تُعاد الخطبة للتعديل بأحد ثلاثة أوجه: تظليل مواضع التعديل على الأصل مع بيان نوع كل تعديل، أو إرفاق أصل جديد مع حفظ النسخة السابقة، أو ملاحظة نصية، مع تحديد اللغات المتأثرة والمرحلة التي تعود إليها."]]],["languages","اللغات والتغطية",[["p","تضم قائمة المنصة اليوم خمسين لغة، منها ثلاث عشرة لغة رئيسية تُختار بضغطة واحدة عند الإسناد، والهدف التوسع فيها بحسب حاجة قاصدي الحرمين الشريفين. وتُضاف اللغات وتُعطَّل من شاشة مستقلة دون تعديل في البرمجة."],["p","ولكل عضو لغاته المؤهَّل فيها، فلا تُسند إليه مادة بلغة لم يُعتمد فيها. أما اللغة العربية فهي الأصل الذي يُترجَم منه، فلا تُعدّ لغة ترجمة."],["p","وللمواد أنواع: خطب الجمعة والعيدين وعرفة والاستسقاء والكسوف، والدروس العلمية، والكتب والمطويات والمنشورات والإعلانات والتوجيهات. وتُنسب الخطب والدروس إلى المسجد الحرام أو المسجد النبوي، وما سواها مواد عامة."]]],["quality","ضبط الجودة والمواعيد",[["ul",["لكل مرحلة موعد محدد، ويظهر للمسؤول عنها عدّاد تنازلي يتحول إلى الأحمر عند تجاوزه.","لا تُغلق مرحلة إلا بعد استيفاء متطلباتها؛ والتسجيل الصوتي حين يُطلب شرط للإغلاق.","الرد إلى مرحلة سابقة لا يتم إلا بسبب مكتوب.","تقييم الأعضاء يجمع مؤشرات تلقائية — الالتزام بالمواعيد وعدد مرات الرد — مع تقييم يدوي من الإدارة، ولا يراه إلا الإدارة.","الأرشيف يحفظ كل عمل معتمد مرتَّبًا بنوع المادة، مع نسخه الصوتية، ويُصدَّر منه مستند Word أو ملف PDF على كليشة الهيئة."]]]],["confidentiality","السرية وحماية المواد",[["p","المادة سرية من لحظة استلامها حتى تُنشر رسميًّا. وهذا مضبوط بإجراءات في المنصة نفسها لا بالتوصية وحدها:"],["ul",["كل عضو يوقّع سياسة السرية إلكترونيًّا قبل استلام أي مهمة، وتظهر حالة توقيعه بعلامة دائمة أمامه وأمام الإدارة.","الأصل العربي يُعرض صفحةً صفحة داخل المنصة بعلامة مائية تحمل بريد المستطلِع وتاريخ الاطّلاع، بلا رابط تنزيل ومع منع النسخ.","الملفات الخاصة — صور الهوية وخطابات البنوك والصور الشخصية — لا تُفتح إلا برابط موقّت ينتهي خلال دقائق، ولصاحبها والإدارة فقط.","الصلاحيات مطبَّقة في قاعدة البيانات نفسها لا في الواجهة: المترجم لا يصل إلى ما لم يُسند إليه ولو حاول.","كل تغيير يمر بدوال محكومة، فلا تعديل مباشر على الجداول.","المحذوف من الأرشيف يبقى أسبوعًا قابلًا للاسترجاع ثم يُتلف ملفه وسجله تلقائيًّا."]]]],["roles","الأدوار والصلاحيات",[["roles"],["p","التسجيل مفتوح برابط واحد للمترجمين والمنسقين، ولا يُفعَّل الحساب إلا بمراجعة المنسق. والاسم الكامل ورقم الهوية بيانان أساسيان لا يعدّلهما العضو بعد التسجيل، لأنهما يظهران في بطاقة العمل والتصاريح."]]],["hosting","الاستضافة وسيادة البيانات",[["ul",["الخوادم وقاعدة البيانات والملفات كلها في مركز بيانات أوراكل السحابي بمدينة الرياض، داخل المملكة.","لا تغادر بيانات المشروع المملكة: لا قاعدة بيانات خارجية، ولا خدمة ترجمة آلية خارجية، ولا خدمة بريد أجنبية.","الاتصال مشفّر بشهادة سارية، والموقع العام يُقدَّم عبر شبكة توصيل عالمية لسرعة الفتح، أما البيانات فلا تُخزَّن إلا في الرياض.","البرمجيات المستعملة كلها مفتوحة المصدر مستضافة ذاتيًّا، فلا ارتهان لمزوّد ولا رسوم تراخيص.","النطاق الرسمي واحد: الموقع العام للمستفيدين، ومنصة العمل على عنوان فرعي مستقل."]]]],["continuity","النسخ الاحتياطي واستمرارية العمل",[["ul",["نسخة احتياطية كاملة كل ليلة في الثانية والنصف بتوقيت الرياض: قاعدة البيانات والملفات معًا.","النسخ مشفّرة قبل رفعها، وتُحفظ في مخزن أوراكل بالرياض.","جرى اختبار الاسترجاع فعليًّا من نسخة احتياطية للتأكد من صلاحيتها، لا الاكتفاء بوجودها.","النسخ القديمة تُنظَّف تلقائيًّا بحسب مدة محددة، فلا تتراكم بلا حاجة."]]]],["governance","الحوكمة والتوثيق",[["p","لكل مادة سجل زمني كامل: من أنشأها، ومن استلم كل مرحلة، ومتى أُغلقت، ومن ردّها ولماذا، ومتى اعتُمدت. السجل لا يُحذف ولا يُعدَّل، ويُرجع إليه عند المراجعة أو المساءلة."],["p","وللإدارة قناة مراسلات رسمية داخل المنصة: تعميم أو توجيه أو تحذير أو دعوة، نصًّا أو ملف PDF، يُرسل إلى الجميع أو إلى فئة أو إلى أشخاص بأعيانهم، ويوقّع العضو عليه «اطّلعت وأوقّع بالعلم»، فتظهر للإدارة قائمة من اطّلع ومن وقّع ومن لم يفعل."],["p","وتصل إشعارات البريد تلقائيًّا: للمترجم عند إسناد مهمة إليه ببياناتها وموعدها، وللمنسقين ومدير المشروع عند اكتمال جميع مراحل لغة."]]],["outputs","المخرجات",[["ul",["ترجمة معتمدة لكل لغة على كليشة الهيئة، تُطبع أو تُصدَّر Word أو PDF بترقيم صفحات منضبط.","أرشيف مرتَّب بنوع المادة وتاريخها ولغتها، مع تسجيلاتها الصوتية.","تصدير بيانات الفريق إلى Excel أو Word أو PDF على الكليشة، باختيار الأعضاء والحقول، مع عنوان للكشف وأعمدة فارغة للتوقيع أو الحضور.","بطاقات عمل بمقاس الهوية الوطنية بصورة العضو ورقم عضويته ولغاته وتوقيع المسؤول، تُصمَّم داخل المنصة وتُطبع عشرًا في الصفحة، وتظهر للعضو في حسابه بعد اعتمادها.","الحسابات البنكية للمستحقات، داخل المملكة وخارجها، موثَّقة بخطاب من البنك."]]]],["next","آفاق التوسع",[["p","ما يلي مقترحات لم تُنفَّذ بعد، تُعرض للنظر لا بوصفها التزامًا:"],["ul",["التوسع في اللغات وفق الحاجة، وضم مترجمين جدد بالآلية نفسها.","تطبيق للجوال للمستفيدين، أو ربط المنصة بالقنوات الرسمية للنشر الآلي.","لوحة مؤشرات للإدارة العليا: معدلات الإنجاز والتأخير لكل لغة وكل فترة.","ربط التسجيلات الصوتية بالنشر المباشر أثناء الخطبة.","توسيع الأرشيف ليشمل الترجمات السابقة قبل المنصة."]]]]]}'::jsonb)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------
-- فتح الصفحة: عضو مفعّل، أو زائر معه الرمز الصحيح
-- ---------------------------------------------------------------------
create or replace function public.open_page(p_key text, p_code text default null)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare v_row public.page_content;
begin
  select * into v_row from public.page_content where key = p_key;
  if v_row.key is null then raise exception 'الصفحة غير موجودة'; end if;

  -- أعضاء المنصة المفعّلون يرونها بلا رمز
  if exists (select 1 from public.profiles p where p.id = auth.uid() and p.status = 'active') then
    return v_row.content;
  end if;

  if v_row.code_hash is null then return v_row.content; end if;

  if p_code is null or length(trim(p_code)) = 0 then
    raise exception 'REQUIRE_CODE' using errcode = '42501';
  end if;
  if crypt(trim(p_code), v_row.code_hash) <> v_row.code_hash then
    raise exception 'رمز الاطّلاع غير صحيح' using errcode = '42501';
  end if;
  return v_row.content;
end $$;

grant execute on function public.open_page(text, text) to anon, authenticated;

-- هل تحتاج الصفحة رمزًا؟ سؤال لا يكشف المحتوى
create or replace function public.page_needs_code(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select code_hash is not null from public.page_content where key = p_key), false)
     and not exists (select 1 from public.profiles p where p.id = auth.uid() and p.status = 'active')
$$;

grant execute on function public.page_needs_code(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- ضبط الرمز وتعديل المحتوى — لمدير المشروع
-- ---------------------------------------------------------------------
create or replace function public.set_page_code(p_key text, p_code text)
returns void language plpgsql security definer set search_path = public, extensions as $$
begin
  if not public.is_manager() then raise exception 'ضبط رمز الاطّلاع لمدير المشروع' using errcode = '42501'; end if;
  if p_code is null or length(trim(p_code)) = 0 then
    update public.page_content set code_hash = null, updated_at = now(), updated_by = auth.uid() where key = p_key;
    return;
  end if;
  if length(trim(p_code)) < 4 then raise exception 'رمز الاطّلاع أربعة محارف فأكثر'; end if;
  update public.page_content
     set code_hash = crypt(trim(p_code), gen_salt('bf')), updated_at = now(), updated_by = auth.uid()
   where key = p_key;
  if not found then raise exception 'الصفحة غير موجودة'; end if;
end $$;

grant execute on function public.set_page_code(text, text) to authenticated;

create or replace function public.save_page_content(p_key text, p_content jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_manager() then raise exception 'تعديل الصفحة لمدير المشروع' using errcode = '42501'; end if;
  if p_content is null or jsonb_typeof(p_content) <> 'object' then raise exception 'محتوى غير صالح'; end if;
  insert into public.page_content (key, content, updated_at, updated_by)
  values (p_key, p_content, now(), auth.uid())
  on conflict (key) do update set content = excluded.content, updated_at = now(), updated_by = auth.uid();
end $$;

grant execute on function public.save_page_content(text, jsonb) to authenticated;

comment on table public.page_content
  is 'محتوى صفحة التعريف ورمز الاطّلاع عليها — لا يُقرأ إلا عبر open_page (ملاحظة ٩١)';
